export const hymns = catholicSections
  .flatMap(({ name, titles }) => titles.map(([number, title]) => ({ section: name, number, title })))
  .map((hymn, index) => ({
    ...hymn,
    id: `catholic-${index + 1}`,
    language: 'ctd',
    lyrics: lyricsByNumber[`${hymn.number}:${hymn.title}`] ?? lyricsByNumber[hymn.number],
  }));

